"""Code shown on the Code tab: how to reproduce each case with PINNeAPPle (the 1D script runs as is)."""

SNIPPETS = {
    "fin": {"title": "1D fin: complete script, runs as is (about 20 s on a CPU)", "file": "fin_h_from_thermocouples.py",
            "code": '# pip install pinneapple\n# Convection coefficient h of a pin fin from thermocouple readings, with a physics-informed network (PINNeAPPle).\nimport torch\nfrom pinneapple_physics.pinn_solver.factory.pinn_factory import PINN, NeuralNetwork, PINNFactory, PINNProblemSpec\n\n# --- your fin and your readings ------------------------------------------------------------------------\nk, D, L = 16.0, 0.005, 0.050                 # conductivity W/m.K, diameter m, length m\nT_wall, T_air = 80.0, 25.0                    # °C\nx_mm = [10, 20, 30, 40, 50]                   # thermocouple positions from the wall\nT_read = [65.1, 54.9, 47.7, 43.3, 42.9]       # their readings, °C\n\n# --- the physics, written as equations (xi = x/L, theta = (T - T_air) / (T_wall - T_air)) -----------------\nspec = PINNProblemSpec(\n    pde_residuals=["Derivative(T(xi), (xi, 2)) - c_fin*h*T(xi)"],          # fin equation, m^2 = 4h/(kD)\n    conditions=[{"name": "wall", "equation": "T(xi) - 1"},                   # wall temperature at xi = 0\n                {"name": "tip", "equation": "Derivative(T(xi), xi) + c_tip*h*T(xi)"}],   # convective tip, xi = 1\n    independent_vars=["xi"], dependent_vars=["T"],\n    inverse_params=["h"],                                                     # unknown: learned with the field\n    constants={"c_fin": 4 * L**2 / (k * D), "c_tip": L / k},\n    loss_weights={"pde": 1.0, "conditions": 10.0, "data": 100.0},\n)\nloss_fn = PINNFactory(spec).generate_loss_function()\nnet = NeuralNetwork(num_inputs=1, num_outputs=1, num_layers=3, num_neurons=32, activation=torch.nn.Tanh())\nmodel = PINN(net, inverse_params_names=["h"], initial_guesses={"h": 100.0})   # start 4x off on purpose\n\nxi = torch.linspace(0, 1, 200).reshape(-1, 1).requires_grad_(True)\nbatch = {\n    "collocation": (xi,),\n    "conditions": [(torch.zeros(1, 1, requires_grad=True),), (torch.ones(1, 1, requires_grad=True),)],\n    "data": ((torch.tensor(x_mm, dtype=torch.float32).reshape(-1, 1) / (L * 1000),),\n             ((torch.tensor(T_read) - T_air) / (T_wall - T_air)).reshape(-1, 1)),\n}\nopt = torch.optim.Adam([{"params": net.parameters(), "lr": 3e-3},\n                        {"params": model.inverse_params.parameters(), "lr": 0.5}])\nsched = torch.optim.lr_scheduler.StepLR(opt, step_size=800, gamma=0.3)\nfor step in range(2001):\n    opt.zero_grad()\n    loss, _ = loss_fn(model, batch)\n    loss.backward()\n    opt.step()\n    sched.step()\n    if step % 500 == 0:\n        print(f"step {step:4d}  h = {model.inverse_params[\'h\'].item():6.2f} W/m2K")\n\n# heat the fin removes: Fourier\'s law at the wall, from the network\'s own derivative\nx0 = torch.zeros(1, 1, requires_grad=True)\ndT = torch.autograd.grad(model(x0).sum(), x0)[0].item() * (T_wall - T_air) / L\nprint(f"h = {model.inverse_params[\'h\'].item():.1f} W/m2K, Q = {-k * 3.14159 * D**2 / 4 * dT:.3f} W")\n'},
    "plate": {"title": "2D plate: the problem as PINNeAPPle sees it (core; the full script is linked)", "file": "examples/use_cases/fin_convection_inverse/plate_2d.py",
              "code": '# pip install pinneapple\n# The 2D plate: same idea, one more coordinate and a heat source. Full script with checks:\n#   git clone https://github.com/PINNeAPPle-Labs/PINNeAPPle && cd PINNeAPPle\n#   python examples/use_cases/fin_convection_inverse/plate_2d.py\nimport torch\nfrom pinneapple_physics.pinn_solver.factory.pinn_factory import PINN, NeuralNetwork, PINNFactory, PINNProblemSpec\n\nL, t, k = 0.100, 0.001, 200.0          # plate length scale, thickness, conductivity (aluminium)\nq_flux, dT = 20_000.0, 50.0            # W/m2 under the device, temperature scale\n\ndef S(xi, eta):                        # device footprint (smooth square), as a function of the inputs\n    w = 0.02\n    sig = lambda s: 0.5 * (1 + torch.tanh(s / w))\n    return sig(0.1 - torch.abs(xi - 0.3)) * sig(0.1 - torch.abs(eta - 0.3))\n\nspec = PINNProblemSpec(\n    # k t (T_xx + T_yy) - 2 h (T - T_air) + q\'\' = 0, scaled\n    pde_residuals=["Derivative(T(xi, eta), (xi, 2)) + Derivative(T(xi, eta), (eta, 2))"\n                   " - c_h*h*T(xi, eta) + c_q*S(xi, eta)"],\n    conditions=[{"name": "left",   "equation": "Derivative(T(xi, eta), xi)"},     # adiabatic edges\n                {"name": "right",  "equation": "Derivative(T(xi, eta), xi)"},\n                {"name": "bottom", "equation": "Derivative(T(xi, eta), eta)"},\n                {"name": "top",    "equation": "Derivative(T(xi, eta), eta)"}],\n    independent_vars=["xi", "eta"], dependent_vars=["T"], inverse_params=["h"],\n    constants={"c_h": 2 * L**2 / (k * t), "c_q": q_flux * L**2 / (k * t * dT)},\n    exogenous={"S": S},\n    loss_weights={"pde": 1.0, "conditions": 1.0, "data": 50.0},\n)\nloss_fn = PINNFactory(spec).generate_loss_function()\nnet = NeuralNetwork(num_inputs=2, num_outputs=1, num_layers=4, num_neurons=48, activation=torch.nn.Tanh())\nmodel = PINN(net, inverse_params_names=["h"], initial_guesses={"h": 60.0})\n# batch = {"collocation": (xi, eta), "conditions": [left, right, bottom, top points], "data": ((xi_s, eta_s), theta_s)}\n# then the same Adam loop as the fin; plate_2d.py adds collocation near the device and the finite-volume check.\n'},
    "block": {"title": "3D block: the problem as PINNeAPPle sees it (core; the full script is linked)", "file": "examples/use_cases/fin_convection_inverse/block_3d.py",
              "code": '# pip install pinneapple\n# The 3D block: a chip\'s flux on the bottom, the fan on top, thermocouples only on top. Full script with checks:\n#   git clone https://github.com/PINNeAPPle-Labs/PINNeAPPle && cd PINNeAPPle\n#   python examples/use_cases/fin_convection_inverse/block_3d.py      # ~30 min on a CPU, minutes on a GPU\nimport math\nimport torch\nfrom pinneapple_physics.pinn_solver.factory.pinn_factory import PINN, PINNFactory, PINNProblemSpec\n\nL, k, q_flux, dT = 0.040, 50.0, 1e5, 50.0          # block size, steel conductivity, chip flux W/m2, temp. scale\nd = lambda v: f"Derivative(T(xi, eta, zeta), {v})"\n\ndef chip_footprint(xi, eta):           # 10 x 10 mm chip, centred, smooth edges\n    w = 0.06\n    sig = lambda s: 0.5 * (1 + torch.tanh(s / w))\n    return sig(0.125 - torch.abs(xi - 0.5)) * sig(0.125 - torch.abs(eta - 0.5))\n\nspec = PINNProblemSpec(\n    pde_residuals=["Derivative(T(xi, eta, zeta), (xi, 2)) + Derivative(T(xi, eta, zeta), (eta, 2))"\n                   " + Derivative(T(xi, eta, zeta), (zeta, 2))"],                       # Laplace\n    conditions=[{"name": "chip (bottom)", "equation": f"{d(\'zeta\')} + c_q*S(xi, eta, zeta)", "weight": 10.0},\n                {"name": "fan (top)",     "equation": f"{d(\'zeta\')} + c_t*h*T(xi, eta, zeta)", "weight": 10.0}],\n    independent_vars=["xi", "eta", "zeta"], dependent_vars=["T"], inverse_params=["h"],\n    constants={"c_q": q_flux * L / (k * dT), "c_t": L / k},\n    exogenous={"S": lambda xi, eta, *_: chip_footprint(xi, eta)},\n    loss_weights={"pde": 5.0, "conditions": 10.0, "data": 50.0},\n)\n\nclass SideAdiabaticNet(torch.nn.Module):\n    """Adiabatic sides built in: inputs cos(pi x), cos(pi y) have zero slope at x, y = 0 and 1."""\n    def __init__(self, width=64, depth=4):\n        super().__init__()\n        layers, n = [], 3\n        for _ in range(depth):\n            layers += [torch.nn.Linear(n, width), torch.nn.Tanh()]\n            n = width\n        self.mlp = torch.nn.Sequential(*layers, torch.nn.Linear(n, 1))\n    def forward(self, x):\n        return self.mlp(torch.cat([torch.cos(math.pi * x[:, :1]), torch.cos(math.pi * x[:, 1:2]), 4 * x[:, 2:3]], 1))\n\nmodel = PINN(SideAdiabaticNet(), inverse_params_names=["h"], initial_guesses={"h": 40.0})\n# Adam, then an L-BFGS polish; h is also recovered from the energy balance on the learned top face:\n#   h = P / integral of (T_top - T_air) dA      (block_3d.py reports both)\n'},
}
